package com.tregy.backend.controller;
import com.tregy.backend.dto.request.UpdateMeRequestDTO;import com.tregy.backend.dto.response.UserResponseDTO;import com.tregy.backend.service.MeService;import com.tregy.backend.service.support.AppUserPrincipal;import jakarta.validation.Valid;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/me") public class MeController{private final MeService service;public MeController(MeService service){this.service=service;}@GetMapping UserResponseDTO get(@AuthenticationPrincipal AppUserPrincipal p){return service.get(p.userId());}@PatchMapping UserResponseDTO update(@AuthenticationPrincipal AppUserPrincipal p,@Valid @RequestBody UpdateMeRequestDTO r){return service.update(p.userId(),r);}}
